private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> left = node.left;
    if (left == null) {
        return node;
    }
    TreeNode<T> leftRight = left.right;
    TreeNode<T> parent = node.parent;
    // perform rotation
    left.right = node;
    node.left = leftRight;
    // update parents
    left.parent = parent;
    node.parent = left;
    if (leftRight != null) {
        leftRight.parent = node;
    }
    if (parent != null) {
        if (parent.left == node) {
            parent.left = left;
        } else if (parent.right == node) {
            parent.right = left;
        }
    }
    return left;
}

