        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev != null) {
        prev.next = next;
    } else {
        node.list.head = next;
    }
    if (next != null) {
        next.prev = prev;
    } else {
        node.list.tail = prev;
    }
    node.prev = null;
    node.next = null;
    node.list.size--;
    return true;
}

